<?php declare(strict_types=1);namespace App\Tests\Imperium\Runtime;use App\Imperium\Runtime\Senate\SenatePersonaFindingGovernanceCognitionAuthorityResolver;use PHPUnit\Framework\TestCase;final class SenatePersonaPracticeFindingGovernanceBoundaryTest extends TestCase{public function testFindingGatewayIsClaimBoundAndPracticeStopsAlone():void{$r=dirname(__DIR__,3);$a=new SenatePersonaFindingGovernanceCognitionAuthorityResolver(sys_get_temp_dir());foreach(['practice','governance','consistency','security']as$j)self::assertTrue($a->supports('senate-persona-confirmation','finding-'.$j));$g=(string)file_get_contents($r.'/src/Imperium/Runtime/Senate/SymfonyAiSenatorFindingCognitionGateway.php');$s=(string)file_get_contents($r.'/src/Imperium/Runtime/Senate/SubordinatePersonaPracticeFindingService.php');$ai=(string)file_get_contents($r.'/config/packages/ai.yaml');self::assertStringContainsString('GovernanceCognitionInvoker',$g);self::assertStringNotContainsString('AgentInterface',$g);foreach(['senator_finding_practice','senator_finding_governance','senator_finding_consistency','senator_finding_security']as$n)self::assertStringNotContainsString($n,$g.$ai);self::assertStringContainsString("'remaining_jurisdictions'=>['governance','consistency','security']",$s);self::assertStringContainsString('PRACTICE_FINDING_SEALED_PENDING_REMAINING_FINDINGS',$s);self::assertStringContainsString("'senate_disposition_authority'=>false",$s);self::assertStringContainsString("'execution_authority'=>false",$s);}}
